import{R as e,e as o,f as n,U as i}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Attio","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/attio.md","filePath":"integrations/crm/attio.md","lastUpdated":1775908585000}'),a={name:"integrations/crm/attio.md"};function r(s,t,l,c,h,g){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="attio" tabindex="-1">Attio <a class="header-anchor" href="#attio" aria-label="Permalink to &quot;Attio&quot;">​</a></h1><p>Follow the below steps to connect to the Attio API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Attio as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-attio-api" tabindex="-1">Step 2. Connect to the Attio API <a class="header-anchor" href="#step-2-connect-to-the-attio-api" aria-label="Permalink to &quot;Step 2. Connect to the Attio API&quot;">​</a></h3><ol><li>Go to <a href="https://www.avochato.com/" target="_blank">Attio</a> and login to your account.</li><li>Click on your profile dropdown on the top-left of the screen, and select <strong>Account Settings</strong>.</li><li>In the left-hand sidebar menu, click on <strong>Developers</strong>.</li><li>Click the <strong>Create Access Token</strong> button.</li><li>Provide <strong>Read-Write</strong> access to all permissions.</li><li>Click the <strong>Save Changes</strong> button.</li><li>Copy the <strong>Access Token</strong> from Attio and paste in the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(a,[["render",r]]);export{p as __pageData,m as default};
